import json
with open('/app/resources/treasury_bulletin_2016_12.json', 'r') as f:
    data = json.load(f)

# Search for Outer Continental Shelf in the content
def find_ocs(elems):
    results = []
    for el in elems:
        if isinstance(el, dict):
            if el.get('content') and 'Outer Continental Shelf' in str(el.get('content')):
                results.append(el)
            if 'elements' in el:
                results.extend(find_ocs(el['elements']))
    return results

# Search through the document elements
for elem in data.get('document', {}).get('elements', []):
    content = elem.get('content', '')
    if content and 'Outer Continental Shelf' in str(content):
        print('Found:', content[:500])
